static inline void notify_pressure(int container_id, int level) {
  if (level < THRESHOLD) return;
  int cpu = get_current_cpu();
  batch_push(batch[cpu], container_id);
  if (batch_len(batch[cpu]) >= BATCH_LIMIT)
    batch_flush(cpu);
}
```

